/* ------------------------------------------------------------------ *
 *  Access
 *  A soft gate, not a vault: this is a client-side app, so the PIN keeps
 *  an honest person out of payroll — it is not protection against someone
 *  determined and technical. Sized for a small shop, deliberately.
 * ------------------------------------------------------------------ */
const ROLE_LABEL = { owner: "Full access", writer: "Service writer" };
const DEFAULT_WRITER_TABS = ["inv", "exp", "hrs", "prod", "imp"];
const ACCESS_SEED = 2;
const TAB_LABELS = {
  dash: "Dashboard", inv: "Invoices", exp: "Expenses", hrs: "Hours",
  pay: "Payroll", pen: "Pension", prod: "Productivity", parts: "Parts analysis", activity: "Activity", cash: "Cash & bank", imp: "Import", set: "Settings",
};
const WRITER_DENIED = ["set", "parts", "activity"]; // productivity is open to the office, but as an efficiency-only view (no money)


const accessOf = (s) => s.access || { writerTabs: DEFAULT_WRITER_TABS };
const writerTabs = (s) => accessOf(s).writerTabs || DEFAULT_WRITER_TABS;
/* null means the cash accounts only — the writer's view is a cash figure, so
   summing the cards and deposits into it would be the wrong number under the wrong name */
const writerAccounts = (s) => accessOf(s).writerAccounts ?? null;
const writerSeesAccount = (s, a) => {
  const allow = writerAccounts(s);
  return allow === null ? a.kind === "Cash" : allow.includes(a.id);
};
const visibleAccounts = (s, me) => {
  const all = accounts(s);
  if (!me || me.role === "owner") return all;
  return all.filter((a) => writerSeesAccount(s, a));
};
const canSeeAccount = (s, me, id) => visibleAccounts(s, me).some((a) => a.id === id);
const canSee = (s, me, tab) => {
  if (!me) return false;
  if (me.role === "owner") return true;
  if (WRITER_DENIED.includes(tab)) return false;
  return writerTabs(s).includes(tab);
};

