/* staff are keyed by name, which is what jobs and pay runs already store */
const staffList = (s) => (s.staff && s.staff.length ? s.staff : (s.techs || ["Unassigned"]).map((n) => ({ name: n, rate: "", commissionRate: "", health: "", active: true })));
const staffOpen = (s) => staffList(s).filter((a) => a.active !== false);
const staffRec = (s, name) => staffList(s).find((a) => a.name === name) || null;
const staffOptions = (s, current) => {
  const list = staffOpen(s);
  const names = list.map((a) => a.name);
  if (current && !names.includes(current)) names.push(current);
  return names.map((n) => ({ v: n, l: n }));
};
const accounts = (s) => (s.accounts && s.accounts.length ? s.accounts : DEFAULT_ACCOUNTS);
const openAccounts = (s) => accounts(s).filter((a) => a.active !== false);
const accName = (s, id) => accounts(s).find((a) => a.id === id)?.name || id || "—";
const accOptions = (s, current) => {
  const list = openAccounts(s);
  if (current && !list.some((a) => a.id === current)) {
    const a = accounts(s).find((x) => x.id === current);
    return [...list, { id: current, name: (a?.name || current) + " (closed)" }].map((x) => ({ v: x.id, l: x.name }));
  }
  return list.map((a) => ({ v: a.id, l: a.name }));
};
const defaultAccount = (s, kind) => (openAccounts(s).find((a) => a.kind === kind) || openAccounts(s)[0] || { id: "Bank" }).id;
const accCurrency = (s, id) => accounts(s).find((a) => a.id === id)?.currency || s.base;
// find the open account of a given kind (Cash/Card/Bank) in a given currency —
// lets the payment form offer just Cash / Credit-Debit / Deposit and pair it with
// the currency chosen above, without showing six currency-specific accounts.
const accByKindCur = (s, kind, cur) => openAccounts(s).find((a) => a.kind === kind && a.currency === cur) || null;
const accFeeRate = (s, id) => {
  const a = accounts(s).find((x) => x.id === id);
  if (!a) return 0;
  return a.feeRate === undefined ? (a.kind === "Card" ? CARD_FEE_DEFAULT : 0) : num(a.feeRate);
};

/* ------------------------------------------------------------------ *
 *  Money
 * ------------------------------------------------------------------ */
const num = (v) => {
  if (typeof v === "number") return isFinite(v) ? v : 0;
  if (!v) return 0;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ""));
  return isFinite(n) ? n : 0;
};

function toBase(amount, cur, s) {
  const a = num(amount);
  if (cur === s.base) return a;
  if (cur === "USD" && s.base === "KYD") return a * s.usdToKyd;
  if (cur === "KYD" && s.base === "USD") return a / s.usdToKyd;
  return a;
}

/* the way back out, so an account can report in the currency it actually holds */
function fromBase(amount, cur, s) {
  const a = num(amount);
  if (cur === s.base) return a;
  if (cur === "USD" && s.base === "KYD") return a / s.usdToKyd;
  if (cur === "KYD" && s.base === "USD") return a * s.usdToKyd;
  return a;
}

function money(n, cur = "KYD") {
  const sign = n < 0 ? "-" : "";
  const v = Math.abs(num(n)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${sign}${cur === "USD" ? "US$" : "CI$"}${v}`;
}

/* ------------------------------------------------------------------ *
 *  Storage + merge
 * ------------------------------------------------------------------ */
async function readShared(key) {
  try {
    if (key === LKEY) return await loadLedger();
    if (key === SKEY) return await loadSettings();
    return null;
  } catch {
    return null;
  }
}

function mergeList(a = [], b = []) {
  const m = new Map();
  [...a, ...b].forEach((x) => {
    const prev = m.get(x.id);
    if (!prev || (x.updatedAt || 0) >= (prev.updatedAt || 0)) m.set(x.id, x);
  });
  return [...m.values()];
}

function mergeLedger(a, b) {
  return {
    invoices: mergeList(a?.invoices, b?.invoices),
    expenses: mergeList(a?.expenses, b?.expenses),
    payroll: mergeList(a?.payroll, b?.payroll),
    cashTx: mergeList(a?.cashTx, b?.cashTx),
    timesheets: mergeList(a?.timesheets, b?.timesheets),
  };
}

const live = (list) => (list || []).filter((x) => !x.deleted);

/* ------------------------------------------------------------------ *
 *  Derived numbers
 * ------------------------------------------------------------------ */
const invTotal = (inv) =>
  inv.total !== undefined && inv.total !== "" && inv.total !== null
    ? num(inv.total)
    : num(inv.labor) + num(inv.partsCharged) + num(inv.other); // old invoices keep their itemised sum
// convert an amount between two currencies using the shop's rate (via base)
const convert = (amount, from, to, s) => {
  if (!from || !to || from === to) return num(amount);
  return fromBase(toBase(amount, from, s), to, s);
};
// a payment made in another currency (e.g. USD on a KYD invoice) is converted into
// the invoice's currency before it reduces the balance — otherwise US$100 wrongly
// wipes CI$100 off the owing instead of its true KYD value.
const payInInvCur = (p, inv, s) => convert(num(p.amount), payCur(p, inv), inv.currency || "KYD", s);
const invPaid = (inv, s) => (inv.payments || []).filter((p) => !payPending(p)).reduce((sum, p) => sum + payInInvCur(p, inv, s), 0);
const invPendingAmt = (inv, s) => (inv.payments || []).filter((p) => payPending(p)).reduce((sum, p) => sum + payInInvCur(p, inv, s), 0);
const invHasPending = (inv) => (inv.payments || []).some((p) => payPending(p));
const invCollected = (inv) => !!inv.collectedAt;
// the watch-list: the car has left but the invoice still owes money
const invLeftUnpaid = (inv, s) => invCollected(inv) && invDue(inv, s) > 0.004;
/* the customer pays the full amount; the bank keeps a slice of card takings */
const cardFee = (p) => r2(num(p.amount) * num(p.feeRate || 0));
// a card account can route its takings into a deposit account (card = the method,
// deposit = where the money lands). Falls back to the payment's own account.
const depositTarget = (s, accountId) => {
  const a = accounts(s).find((x) => x.id === accountId);
  return a && a.depositsInto ? a.depositsInto : accountId;
};
const netDeposit = (p) => r2(num(p.amount) - cardFee(p));
// A payment the customer makes DIRECTLY by bank deposit isn't guaranteed until the
// bank shows it, so it's held "pending" until confirmed. Card payments are secure
// (they always arrive, a day or two later) even though they route into a deposit
// account — so only a directly-chosen Bank account triggers pending, not the routing.
const landsInBank = (s, p) => {
  const a = accounts(s).find((x) => x.id === p.account); // the account actually chosen
  return !!a && a.kind === "Bank";
};
const payPending = (p) => p.pending === true;
const payCur = (p, inv) => p.currency || inv?.currency || "KYD";
const invDue = (inv, s) => Math.max(0, invTotal(inv) - invPaid(inv, s));
const invProfit = (inv) => 0; // margin lives in analytics now, not the books
const invStatus = (inv, s) => {
  if (invHasPending(inv)) return "PENDING";
  const d = invDue(inv, s);
  if (d <= 0.004) return "PAID";
  return invPaid(inv, s) > 0 ? "PARTIAL" : "OPEN";
};

/* --- payroll maths --- */
const r2 = (n) => Math.round(num(n) * 100) / 100;
const isV2 = (p) => p.schema === 2;

const isSalaried = (p) => p.payType === "monthly";

// a salaried person's overtime rate: yearly (monthly x12) / 52 weeks / 45 hrs, x1.5
// a salaried person's average hourly rate: yearly (monthly x12) / 52 weeks / 45 hrs.
// This is the basis for both overtime and any unpaid-day deduction.
const salaryHourly = (p) => {
  const weekly = (num(p.salary) * 12) / 52;
  return weekly / (num(p.fullWeekHours) || 45);
};
const salaryOtRate = (p) => salaryHourly(p) * num(p.otMultiplier || 1.5);

// Unpaid days: the month grid holds a day list. A day explicitly set to 0 hours
// is an unpaid day — deduct 8 x the average hourly rate. A BLANK day is a normal
// paid day and deducts nothing. Only an explicit 0 docks pay.
const HOURS_PER_DAY = 8;
const unpaidDays = (p) => (p.monthDays || []).filter((d) => d.hours === "0" || d.hours === 0).length;
const salaryDeduction = (p) => (isSalaried(p) ? r2(unpaidDays(p) * HOURS_PER_DAY * salaryHourly(p)) : 0);

// count leave markers on a pay run's month grid
const leaveCount = (p, kind) => (p.monthDays || []).filter((d) => d.leave === kind).length;

const payRegular = (p) =>
  !isV2(p) ? 0 : isSalaried(p) ? r2(num(p.salary) - salaryDeduction(p)) : r2(num(p.hours) * num(p.rate));
const payOT = (p) =>
  !isV2(p) ? 0 : isSalaried(p) ? r2(num(p.otHours) * salaryOtRate(p)) : r2(num(p.otHours) * num(p.rate) * num(p.otMultiplier || 1.5));
const payCommission = (p) => (isV2(p) && !isSalaried(p) ? r2(num(p.hoursProduced) * num(p.commissionRate)) : 0);
const payGross = (p) => (isV2(p) ? r2(payRegular(p) + payOT(p) + payCommission(p)) : num(p.amount));

// Pension: total contribution is a % of gross. The shop pays "pensionShopPct" of
// that total, the employee pays the rest (deducted). Default: employee 50 / shop 50,
// which is the old "employee 5% + full company match" expressed as a split.
const pensionTotal = (p) => (isV2(p) ? r2(payGross(p) * num(p.pensionRate ?? 0.05) * 2) : 0);
const pensionShopShare = (p) => (p.pensionShopPct !== undefined && p.pensionShopPct !== "" ? num(p.pensionShopPct) : 50);
const payPension = (p) => (isV2(p) ? r2(pensionTotal(p) * (1 - pensionShopShare(p) / 100)) : 0); // employee's deducted share
const payOther = (p) => (isV2(p) ? num(p.deductions) : 0);

// Health: two amounts entered by hand per pay run — the employee's share (a
// deduction) and the shop's share (a cost). No premium, no proration: whatever
// is typed is what appears. Old slips carried only p.health (the employee part),
// so that still reads as the employee deduction with no shop share.
const payHealthEmployee = (p) => (isV2(p) ? num(p.health) : 0);
const payHealthShop = (p) => (isV2(p) ? num(p.healthShop) : 0);

const payHealth = (p) => payHealthEmployee(p); // employee's share is what's deducted
const payDeductions = (p) => r2(payOther(p) + payPension(p) + payHealth(p));
const payNet = (p) => (isV2(p) ? r2(payGross(p) - payDeductions(p)) : num(p.amount));
const payMatch = (p) => (isV2(p) ? r2(pensionTotal(p) * (pensionShopShare(p) / 100)) : 0); // shop share of pension
// true wage cost to the shop: gross + pension match + the shop's half of health
const payCost = (p) => r2(payGross(p) + payMatch(p) + payHealthShop(p));

function accountBalance(led, account, s) {
  let bal = 0;
  live(led.cashTx).forEach((t) => {
    const v = toBase(t.amount, t.currency, s);
    if (t.type === "transfer") {
      if (t.account === account) bal -= v;
      if (t.toAccount === account) bal += v;
      return;
    }
    if (t.account !== account) return;
    bal += t.type === "withdrawal" ? -v : v;
  });
  live(led.invoices).forEach((i) =>
    (i.payments || []).forEach((p) => {
      if (!payPending(p) && depositTarget(s, p.account) === account) bal += toBase(netDeposit(p), payCur(p, i), s);
    })
  );
  live(led.expenses).forEach((e) => {
    if (e.account === account) bal -= toBase(e.amount, e.currency, s);
  });
  live(led.payroll).forEach((p) => {
    if (p.account === account && p.paidDate) bal -= toBase(payNet(p), p.currency, s);
  });
  return bal;
}

const inMonth = (d, ym) => (d || "").slice(0, 7) === ym;

